    <div class="main-panel @(_isThreadOpen ? "" : "full-width")">
        @if (_selectedChannel is not null)
        {
            <div class="main-header">
                <h3># @_selectedChannel.Name</h3>
                <span class="header-desc">@_selectedChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @foreach (var msg in _messages)
                {
                    <MessageItem Message="msg"
                                 ReplyCount="GetReplyCount(msg.Id)"
                                 OnOpenThread="OpenThread"
                                 OnReact="HandleReaction" />
                }
            </div>

            <MessageInput Placeholder="@($"Message # {_selectedChannel.Name}")"
                          OnSend="SendMessage" />
        }
        else
        {
            <div class="no-channel">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_isThreadOpen)
    {
        <div class="thread-panel-container">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = new();
    private Channel? _selectedChannel;
    private int _selectedChannelId;
    private List<Message> _messages = new();
    private Dictionary<int, ThreadSummary> _threadSummaries = new();
    private bool _loadingMore;
    private bool _hasMoreMessages = true;
    private const int PageSize = 30;

    private bool _isThreadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = new();

    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages.Clear();
        _threadSummaries.Clear();
        _hasMoreMessages = true;
        CloseThread();

        if (_selectedChannel is not null)
        {
            await LoadMessages();
            await ChatService.MarkChannelReadAsync(channelId);

            // Update the local unread count
            var idx = _channels.FindIndex(c => c.Id == channelId);
            if (idx >= 0)
            {
                _channels[idx] = _selectedChannel with { UnreadCount = 0 };
                _selectedChannel = _channels[idx];
            }
        }
    }

    private async Task LoadMessages()
    {
        var batch = await ChatService.GetMessagesAsync(_selectedChannelId, _messages.Count, PageSize);
        if (batch.Count < PageSize)
        {
            _hasMoreMessages = false;
        }

        // Prepend older messages (API returns oldest first for skip/take)
        _messages.InsertRange(0, batch);
        BuildThreadSummaries();
    }

    private void BuildThreadSummaries()
    {
        _threadSummaries.Clear();
        var replies = _messages.Where(m => m.ReplyToId.HasValue).ToList();
        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            _threadSummaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt)
            );
        }
    }

    private int GetReplyCount(int messageId)
    {
        return _threadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;
    }

    private async Task HandleScroll()
    {
        if (_loadingMore || !_hasMoreMessages) return;

        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('[b-chat-scroll]')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            _loadingMore = true;
            StateHasChanged();

            await LoadMessages();

            _loadingMore = false;
        }
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _isThreadOpen = true;
    }

    private void CloseThread()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadReplies.Clear();
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _selectedChannel is null) return;

        var reply = await ChatService.SendMessageAsync(
            _selectedChannelId, content, _threadRootMessage.Id);

        _threadReplies.Add(reply);
        _messages.Add(reply);
        BuildThreadSummaries();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Update local state optimistically
        var msg = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, new List<string> { "You" }));
            }
        }
    }
}

