+.chat-container {
+    display: flex;
+    height: 100vh;
+    width: 100%;
+    background-color: #313338;
+    color: #dcddde;
+    font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
+}
+
+.sidebar-panel {
+    width: 20%;
+    min-width: 200px;
+    max-width: 280px;
+    flex-shrink: 0;
+}
+
+.main-panel {
+    flex: 1;
+    display: flex;
+    flex-direction: column;
+    min-width: 0;
+    overflow: hidden;
+}
+
+.main-panel.full-width {
+    flex: 1;
+}
+
+.thread-panel-container {
+    width: 25%;
+    min-width: 280px;
+    max-width: 420px;
+    flex-shrink: 0;
+}
+
+.main-header {
+    display: flex;
+    align-items: baseline;
+    gap: 12px;
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+    background-color: #313338;
+    flex-shrink: 0;
+}
+
+.main-header h3 {
+    margin: 0;
+    color: #f2f3f5;
+    font-size: 1rem;
+    font-weight: 700;
+    white-space: nowrap;
+}
+
+.header-desc {
+    font-size: 0.8rem;
+    color: #72767d;
+    white-space: nowrap;
+    overflow: hidden;
+    text-overflow: ellipsis;
+}
+
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 8px 0;
+    display: flex;
+    flex-direction: column;
+    gap: 2px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 12px;
+    font-size: 0.8rem;
+    color: #72767d;
+}
+
+.no-channel {
+    flex: 1;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    color: #72767d;
+    font-size: 1.1rem;
+}
+

